P=pathlib.Path(__file__).parent;T=[int(x) for x in sys.argv[1:]];f=P/'visually-reviewed-towers.json';f.write_text(json.dumps(sorted(set(json.loads(f.read_text())+T))));tag=f'{T[0]}-{T[-1]}';(P/f'visual-review-{tag}.json').write_text(json.dumps({'towers':T,'actual_views_directly_reviewed':len(T)*4,'result':'All four actual views inspected for own shape, solid service walls, intact fine rails, twin service columns, brown base and contained slatted roof. No crop or unsupported details observed.'},indent=2));subprocess.run([sys.executable,str(P/'finish-reviewed.py')],check=True);B=[x for x in json.loads((P/'bundle.json').read_text()) if int(x['tower']) in T];(P/f'bundle-{tag}.json').write_text(json.dumps(B,ensure_ascii=False,indent=2));print('batch',tag,'bytes',sum(x['glbBytes'] for x in B))
